import * as T from './vendor/three.module.min.js';
// Software projection keeps the same real geometry interactive when WebGL is unavailable.
export class SoftRenderer{
 constructor(canvas){this.domElement=canvas;this.ctx=canvas.getContext('2d');if(!this.ctx)throw new Error('Canvas unavailable');this.width=1;this.height=1;this.cache=new WeakMap();this.pixelRatio=1;}
 setPixelRatio(v){this.pixelRatio=Math.min(v,1.4)}
 setSize(w,h){this.width=w;this.height=h;this.domElement.width=Math.round(w*this.pixelRatio);this.domElement.height=Math.round(h*this.pixelRatio);this.ctx.setTransform(this.pixelRatio,0,0,this.pixelRatio,0,0);}
 render(scene,camera){const ctx=this.ctx,w=this.width,h=this.height;ctx.clearRect(0,0,w,h);scene.updateMatrixWorld(true);camera.updateMatrixWorld(true);const vp=new T.Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse),triangles=[];const light=new T.Vector3(-.5,1,.8).normalize();const v=new T.Vector3(),normal=new T.Vector3();const nm=new T.Matrix3();
  const shadow=new T.Vector3(0,-.11,0).applyMatrix4(vp);const sx=(shadow.x+1)*w/2,sy=(1-shadow.y)*h/2;const grad=ctx.createRadialGradient(sx,sy,0,sx,sy,w*.23);grad.addColorStop(0,'rgba(98,49,65,.14)');grad.addColorStop(1,'rgba(98,49,65,0)');ctx.save();ctx.translate(sx,sy);ctx.scale(1,.27);ctx.fillStyle=grad;ctx.translate(-sx,-sy);ctx.fillRect(sx-w*.3,sy-w*.3,w*.6,w*.6);ctx.restore();
  scene.traverse(o=>{if(!o.isMesh||!o.visible)return;let parent=o.parent;while(parent){if(!parent.visible)return;parent=parent.parent}if(o.userData.skipSoft)return;let geo=o.geometry;if(!geo.attributes.color&&!this.cache.has(geo)){const p=geo.attributes.position,ix=geo.index?.array,ns=geo.attributes.normal,positions=[],normals=[];if(p){const put=(a,b,c,na,nb,nc,depth=0)=>{const ab=a.distanceToSquared(b),bc=b.distanceToSquared(c),ca=c.distanceToSquared(a);if(Math.max(ab,bc,ca)>.24&&depth<5){const mab=a.clone().add(b).multiplyScalar(.5),mbc=b.clone().add(c).multiplyScalar(.5),mca=c.clone().add(a).multiplyScalar(.5),nab=na.clone().add(nb).normalize(),nbc=nb.clone().add(nc).normalize(),nca=nc.clone().add(na).normalize();put(a,mab,mca,na,nab,nca,depth+1);put(mab,b,mbc,nab,nb,nbc,depth+1);put(mca,mbc,c,nca,nbc,nc,depth+1);put(mab,mbc,mca,nab,nbc,nca,depth+1);}else{positions.push(...a,...b,...c);normals.push(...na,...nb,...nc)}};for(let i=0;i<(ix?.length??p.count);i+=3){const ids=[ix?ix[i]:i,ix?ix[i+1]:i+1,ix?ix[i+2]:i+2];put(...ids.map(n=>new T.Vector3().fromBufferAttribute(p,n)),...ids.map(n=>ns?new T.Vector3().fromBufferAttribute(ns,n):new T.Vector3(0,1,0)));}const refined=new T.BufferGeometry();refined.setAttribute('position',new T.Float32BufferAttribute(positions,3));refined.setAttribute('normal',new T.Float32BufferAttribute(normals,3));this.cache.set(geo,{refined});}}geo=this.cache.get(geo)?.refined??geo;const mat=Array.isArray(o.material)?o.material[0]:o.material;if(!mat?.color)return;const pos=geo.attributes.position,norm=geo.attributes.normal,index=geo.index?.array;if(!pos)return;let cached=this.cache.get(geo);if(!cached){cached={xy:new Float32Array(pos.count*3)};this.cache.set(geo,cached)}const p=cached.xy;const matrix=new T.Matrix4().multiplyMatrices(vp,o.matrixWorld);for(let i=0;i<pos.count;i++){v.fromBufferAttribute(pos,i).applyMatrix4(matrix);p[i*3]=(v.x+1)*w/2;p[i*3+1]=(1-v.y)*h/2;p[i*3+2]=v.z;}nm.getNormalMatrix(o.matrixWorld);let hex=mat.color.getHex(),r=(hex>>16)&255,g=(hex>>8)&255,b=hex&255;const count=index?index.length:pos.count;
   for(let i=0;i<count;i+=3){const ai=index?index[i]:i,bi=index?index[i+1]:i+1,ci=index?index[i+2]:i+2,a=ai*3,bb=bi*3,c=ci*3;const cross=(p[bb]-p[a])*(p[c+1]-p[a+1])-(p[bb+1]-p[a+1])*(p[c]-p[a]);if(mat.side!==T.DoubleSide&&cross>=0)continue;const z=(p[a+2]+p[bb+2]+p[c+2])/3;if(z<-1||z>1)continue;let shade=.85;if(norm){normal.fromBufferAttribute(norm,ai).applyNormalMatrix(nm);shade=.66+Math.max(0,normal.dot(light))*.34;}if(mat.vertexColors&&geo.attributes.color){const colors=geo.attributes.color,tint=new T.Color().setRGB((colors.getX(ai)+colors.getX(bi)+colors.getX(ci))/3,(colors.getY(ai)+colors.getY(bi)+colors.getY(ci))/3,(colors.getZ(ai)+colors.getZ(bi)+colors.getZ(ci))/3).multiply(mat.color);hex=tint.getHex();r=(hex>>16)&255;g=(hex>>8)&255;b=hex&255;}const opacity=mat.transparent?Math.max(.18,mat.opacity):1;triangles.push({x1:p[a],y1:p[a+1],x2:p[bb],y2:p[bb+1],x3:p[c],y3:p[c+1],z,fill:`rgba(${Math.round(r*shade)},${Math.round(g*shade)},${Math.round(b*shade)},${opacity})`,opacity});}
  });triangles.sort((a,b)=>b.z-a.z);for(const p of triangles){ctx.beginPath();ctx.moveTo(p.x1,p.y1);ctx.lineTo(p.x2,p.y2);ctx.lineTo(p.x3,p.y3);ctx.closePath();ctx.fillStyle=p.fill;ctx.fill();if(p.opacity===1){ctx.strokeStyle=p.fill;ctx.lineWidth=.45;ctx.stroke()}}
 }
 dispose(){this.cache=new WeakMap()}
}
